// Extract all recipe IDs from the validated menu
const hist = $input.first().json;
const validationRaw = hist.properties?.Validation_json?.rich_text?.[0]?.plain_text || '{}';
const validation = JSON.parse(validationRaw);

const recipeIds = Object.values(validation)
  .filter(v => v.id && v.id !== 'new')
  .map(v => v.id);

const chatId = $('Webhook — Déclencher').first().json.body?.chatId
  || hist.properties?.Telegram_chat_id?.number
  || process.env.TELEGRAM_CHAT_ID_PRINCIPAL;

return [{ json: { recipeIds, chatId, historiqueId: hist.id } }];

// Aggregate ingredients from all recipes and prepare Gemini prompt
const recipes = $('Notion — Get recettes validées').all();
const permanent = $('Notion — Garde-manger permanent').all();
const toRestock = $('Notion — À renouveler').all();

// Collect raw ingredients
const rawIngredients = recipes.flatMap(r => {
  const text = r.json.properties?.Ingrédients?.rich_text?.[0]?.plain_text || '';
  return text.split('\n').map(l => l.replace(/^[;,\s]+/, '').trim()).filter(Boolean);
});

// Extract pantry names
const pantryItems = permanent.map(p =>
  p.json.properties?.Article?.title?.[0]?.plain_text || ''
).filter(Boolean);

const restockItems = toRestock.map(p =>
  p.json.properties?.Article?.title?.[0]?.plain_text || ''
).filter(Boolean);

return [{
  json: {
    rawIngredients: rawIngredients.join('\n'),
    pantryItems: pantryItems.join('\n'),
    restockItems: restockItems.join('\n'),
    chatId: $('Code — Extraire IDs recettes').first().json.chatId,
    historiqueId: $('Code — Extraire IDs recettes').first().json.historiqueId
  }
}];

// Parse Gemini response and format Telegram message
const raw = $input.first().json;
const text = raw.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const data = JSON.parse(cleaned);

const categoryEmoji = {
  'Fruits & Légumes': '🥦',
  'Viandes & Poissons': '🥩',
  'Produits laitiers & Œufs': '🥛',
  'Boulangerie': '🥖',
  'Épicerie sèche': '🫙',
  'Conserves & Sauces': '🥫',
  'Surgelés': '🧊',
  'Boissons': '💧',
  'Hygiène & Maison': '🧴'
};

let msg = `🛒 *Liste de courses*\n\n`;
let total = 0;

for (const [cat, items] of Object.entries(data.liste_courses || {})) {
  if (!items || items.length === 0) continue;
  msg += `${categoryEmoji[cat] || '📦'} *${cat}*\n`;
  items.forEach(item => {
    msg += `• ${item.article} — ${item.quantite} ${item.unite}\n`;
    total++;
  });
  msg += '\n';
}

msg += `_Total : ${total} articles_`;

const keyboard = [
  [{ text: '🛒 Envoyer au Drive Intermarché', callback_data: 'send_to_drive' }],
  [{ text: '+ Ajouter un article', callback_data: 'add_custom' }]
];

return [{
  json: {
    listJson: JSON.stringify(data.liste_courses),
    telegramMsg: msg,
    keyboard,
    total,
    chatId: $('Code — Agréger ingrédients').first().json.chatId,
    historiqueId: $('Code — Agréger ingrédients').first().json.historiqueId
  }
}];
